import sys
MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    y = [0] * n
    for i in range(n):
        x, v = data[1 + 2*i], data[2 + 2*i]
        y[x - 1] = v

    # A first selected point must be a prefix maximum; the last must be
    # a suffix minimum, to cover points outside the selected x-range.
    prefix_max = [False] * n
    best = 0
    for i, v in enumerate(y):
        prefix_max[i] = v > best
        best = max(best, v)

    suffix_min = [False] * n
    best = n + 1
    for i in range(n - 1, -1, -1):
        suffix_min[i] = y[i] < best
        best = min(best, y[i])

    # Consecutive selected points i < j in a decreasing sequence may be
    # adjacent in the selected set only if no intervening point lies
    # strictly between their y-coordinates.
    edge = [[False] * n for _ in range(n)]
    for i in range(n):
        yi = y[i]
        for j in range(i + 1, n):
            yj = y[j]
            if yi > yj:
                valid = True
                for k in range(i + 1, j):
                    if yj < y[k] < yi:
                        valid = False
                        break
                edge[i][j] = valid

    ans = 0
    for start in range(n):
        if not prefix_max[start]:
            continue
        dp = [0] * n
        dp[start] = 1
        if suffix_min[start]:
            ans += 1
        for end in range(start + 1, n):
            ways = 0
            for prev in range(start, end):
                if edge[prev][end]:
                    ways += dp[prev]
            dp[end] = ways % MOD
            if suffix_min[end]:
                ans += dp[end]
        ans %= MOD

    # The zero-operation outcome is the full set. It is already counted
    # above exactly when the whole permutation is decreasing.
    if n > 1 and any(y[i] < y[i + 1] for i in range(n - 1)):
        ans += 1
    print(ans % MOD)

if __name__ == '__main__':
    solve()

