from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            events[b].append((a, idx))

        largest = second_largest = 0
        largest_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for a, idx in events[right]:
                if a > largest:
                    second_largest = largest
                    largest = a
                    largest_id = idx
                elif a > second_largest:
                    second_largest = a

            # Every valid subarray ending at right starts after the largest
            # left endpoint among pairs whose right endpoint has activated.
            total += right - largest

            # If the maximum constraint comes from one pair only, removing
            # it relaxes the boundary to the second-largest constraint.
            if largest_id >= 0 and largest > second_largest:
                gains[largest_id] += largest - second_largest

        return total + max(gains)

