        events = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            events[b].append((a, idx))
        first_v = second_v = 0
        first_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0
        for r in range(1, n + 1):
            for a, idx in events[r]:
                if a > first_v:
                    second_v = first_v
                    first_v, first_id = a, idx
                elif a > second_v:
                    second_v = a
            total += r - first_v
            if first_id >= 0 and first_v > second_v:
                gains[first_id] += first_v - second_v
        return total + max(gains)

