import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[:2]
    machines = [tuple(data[2 + 4*i: 6 + 4*i]) for i in range(n)]

    def minimum_cost(k, a, p, b, q):
        best = 10**30
        if p * b <= q * a:
            # S has at least as much production per yen as T.
            # An optimum can use fewer than a units of T.
            for y in range(a):
                x = max(0, (k - b*y + a - 1) // a)
                best = min(best, p*x + q*y)
        else:
            # Symmetrically, an optimum can use fewer than b units of S.
            for x in range(b):
                y = max(0, (k - a*x + b - 1) // b)
                best = min(best, p*x + q*y)
        return best

    def feasible(k):
        total = 0
        for a, p, b, q in machines:
            total += minimum_cost(k, a, p, b, q)
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

