class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # A number with popcount c takes 1 + reductions(c) steps; c=1 is also valid for k>=1.
        valid = [False] * (n + 1)
        for c in range(1, n + 1):
            t = c
            steps = 0
            while t > 1:
                t = t.bit_count()
                steps += 1
            valid[c] = steps <= k - 1

        # Pascal table for choosing ones in the remaining suffix.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        ans = 0
        prefix_ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = n - i - 1
                for suffix_ones in range(remaining + 1):
                    c = prefix_ones + suffix_ones
                    if c >= 1 and valid[c]:
                        ans += comb[remaining][suffix_ones]
                prefix_ones += 1
        return ans % MOD

