def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        adj[u] |= 1 << v
        adj[v] |= 1 << u

    # The equations are A x = 0 over GF(2); isolated vertices have no equation.
    rows = [row for row in adj if row]
    pivot_cols = []
    r = 0
    for c in range(n):
        q = next((i for i in range(r, len(rows)) if (rows[i] >> c) & 1), None)
        if q is None:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(len(rows)):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivot_cols.append(c)
        r += 1

    pivot_set = set(pivot_cols)
    free_cols = [c for c in range(n) if c not in pivot_set]
    # Use bit positions 2 onward when available; this remains within 60 bits.
    offset = 2 if n > 1 and len(free_cols) <= 58 else 0
    values = [0] * n
    for bit, f in enumerate(free_cols):
        vec = 1 << f
        for i, c in enumerate(pivot_cols):
            if (rows[i] >> f) & 1:
                vec |= 1 << c
        for v in range(n):
            if (vec >> v) & 1:
                values[v] |= 1 << (bit + offset)

    if any(x == 0 for x in values):
        print("No")
    else:
        print("Yes")
        print(*values)

