from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]  # clockwise
        size = n * m
        # A state's value is the longest valid continuation beginning at this cell,
        # with the given direction and turn availability. Values only matter at 0/2 cells.
        turned = [[bytearray(size) for _ in range(4)] for _ in range(1)] [0]
        free = [bytearray(size) for _ in range(4)]

        def index(i, j):
            return i * m + j

        for d, (di, dj) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if di > 0 else range(n)
            cols = range(m - 1, -1, -1) if dj > 0 else range(m)
            for i in rows:
                for j in cols:
                    val = grid[i][j]
                    if val == 1:
                        continue
                    idx = index(i, j)
                    ni, nj = i + di, j + dj
                    length = 1
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] in (0, 2) and grid[ni][nj] != val:
                        length += turned[d][index(ni, nj)]
                    turned[d][idx] = length

        for d, (di, dj) in enumerate(dirs):
            nd = (d + 1) % 4
            rows = range(n - 1, -1, -1) if di > 0 else range(n)
            cols = range(m - 1, -1, -1) if dj > 0 else range(m)
            for i in rows:
                for j in cols:
                    val = grid[i][j]
                    if val == 1:
                        continue
                    idx = index(i, j)
                    best = 0
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] in (0, 2) and grid[ni][nj] != val:
                        best = free[d][index(ni, nj)]
                    ndi, ndj = dirs[nd]
                    ni, nj = i + ndi, j + ndj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] in (0, 2) and grid[ni][nj] != val:
                        best = max(best, turned[nd][index(ni, nj)])
                    free[d][idx] = 1 + best

        ans = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    ans = max(ans, 1)
                    for d, (di, dj) in enumerate(dirs):
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] in (0, 2) and grid[ni][nj] == 2:
                            ans = max(ans, 1 + free[d][index(ni, nj)])
        return ans

