from typing import List
from functools import lru_cache

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(-1,1),(1,1),(1,-1),(-1,-1)]
        @lru_cache(None)
        def f(i,j,p,d,used):
            if not (0 <= i < n and 0 <= j < m) or grid[i][j] != (2 if p == 0 else 0):
                return 0
            ni, nj = i+dirs[d][0], j+dirs[d][1]
            best = f(ni,nj,1-p,d,used)
            if not used:
                nd=(d+1)%4
                ni,nj=i+dirs[nd][0],j+dirs[nd][1]
                best=max(best,f(ni,nj,1-p,nd,1))
            return 1+best
        ans=0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    ans= max(ans,1)
                    for d,(di,dj) in enumerate(dirs):
                        ans=max(ans,1+f(i+di,j+dj,0,d,0))
        return ans

