from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))

        # Count valid permutations by their first parity.
        total = 0
        for first_odd in (True, False):
            odd_slots = (n + 1) // 2 if first_odd else n // 2
            even_slots = n - odd_slots
            if odd_slots == len(odds) and even_slots == len(evens):
                total += math.factorial(odd_slots) * math.factorial(even_slots)
        if k > total:
            return []

        answer = []
        previous_odd = None
        for pos in range(n):
            for value in sorted(odds + evens):
                is_odd = value % 2 == 1
                if previous_odd is not None and is_odd == previous_odd:
                    continue

                remaining_odds = len(odds) - int(is_odd)
                remaining_evens = len(evens) - int(not is_odd)
                remaining_positions = n - pos - 1

                if remaining_positions == 0:
                    odd_slots = 0
                elif not is_odd:  # Next position is odd.
                    odd_slots = (remaining_positions + 1) // 2
                else:  # Next position is even.
                    odd_slots = remaining_positions // 2
                even_slots = remaining_positions - odd_slots

                if remaining_odds == odd_slots and remaining_evens == even_slots:
                    block = math.factorial(remaining_odds) * math.factorial(remaining_evens)
                else:
                    block = 0

                if k > block:
                    k -= block
                else:
                    answer.append(value)
                    if is_odd:
                        odds.remove(value)
                    else:
                        evens.remove(value)
                    previous_odd = is_odd
                    break
            else:
                return []

        return answer

