class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            coeff.append(powers[i] if i == j else (powers[i] + powers[j]) % k)

        # dp[i][r] indicates whether variables i onward can sum to residue r.
        dp = [None] * (m + 1)
        dp[m] = bytes([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            row = bytearray(k)
            nxt = dp[i + 1]
            c = coeff[i]
            for d in range(10):
                add = d * c % k
                for r in range(k):
                    if nxt[r]:
                        row[(add + r) % k] = 1
            dp[i] = bytes(row)

        # Greedily maximize each digit while preserving a feasible suffix.
        digits = []
        need = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                rem = (need - d * c) % k
                if dp[i + 1][rem]:
                    digits.append(str(d))
                    need = rem
                    break

        half = ''.join(digits)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

