from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        next_greater = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            next_greater[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        jump = [[-1] * n for _ in range(levels)]
        sums = [[0] * n for _ in range(levels)]
        for i in range(n):
            end = next_greater[i]
            if end < n:
                jump[0][i] = end
            sums[0][i] = nums[i] * (end - i)

        for p in range(1, levels):
            prev_jump = jump[p - 1]
            prev_sum = sums[p - 1]
            cur_jump = jump[p]
            cur_sum = sums[p]
            for i in range(n):
                mid = prev_jump[i]
                if mid != -1:
                    cur_jump[i] = prev_jump[mid]
                    cur_sum[i] = prev_sum[i] + prev_sum[mid]
                else:
                    cur_sum[i] = prev_sum[i]

        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        def required(l, r):
            cur = l
            raised_sum = 0
            for p in range(levels - 1, -1, -1):
                nxt = jump[p][cur]
                if nxt != -1 and nxt <= r + 1:
                    raised_sum += sums[p][cur]
                    cur = nxt
            if cur <= r:
                raised_sum += nums[cur] * (r - cur + 1)
            return raised_sum - (prefix[r + 1] - prefix[l])

        answer = 0
        for left in range(n):
            low, high = left, n - 1
            while low < high:
                mid = (low + high + 1) // 2
                if required(left, mid) <= k:
                    low = mid
                else:
                    high = mid - 1
            answer += low - left + 1
        return answer

