    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for c in s:
            cnt[ord(c) - 97] += 1

        ans = len(s)  # Make the final string empty.
        for k in range(1, max(cnt) + 1):
            # dp[0/1]: minimum cost through the previous letter when it is
            # absent / has exactly k occurrences.
            dp = [cnt[0], abs(cnt[0] - k)]
            for i in range(1, 26):
                ndp = [10**9, 10**9]
                for prev in (0, 1):
                    previous_target = k if prev else 0
                    for cur in (0, 1):
                        current_target = k if cur else 0
                        cost = abs(cnt[i] - current_target)
                        # Increment surplus occurrences of the previous
                        # letter to cover a deficit of this letter.
                        if cnt[i - 1] > previous_target and cnt[i] < current_target:
                            cost -= min(cnt[i - 1] - previous_target,
                                        current_target - cnt[i])
                        ndp[cur] = min(ndp[cur], dp[prev] + cost)
                dp = ndp
            ans = min(ans, dp[0], dp[1])
        return ans

