class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for c in s:
            cnt[ord(c) - 97] += 1
        n = len(s)
        ans = n
        for k in range(1, max(cnt) + 1):
            # dp for whether current letter is absent or has frequency k
            dp = [0, abs(cnt[0] - k)]
            # absent at letter 0 costs deleting all its occurrences
            dp[0] = cnt[0]
            for i in range(1, 26):
                ndp = [10**9, 10**9]
                for prev in (0, 1):
                    for cur in (0, 1):
                        a = 0 if prev == 0 else k
                        b = 0 if cur == 0 else k
                        cost = abs(cnt[i-1] - a) + abs(cnt[i] - b)
                        # Shift surplus from i-1 into a deficit at i.
                        if cnt[i-1] > a and cnt[i] < b:
                            cost -= min(cnt[i-1] - a, b - cnt[i])
                        ndp[cur] = min(ndp[cur], dp[prev] + cost)
                dp = ndp
            ans = min(ans, min(dp))
        return ans

