from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            ans = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    ans.append(i - m + 1)
                    j = pi[j - 1]
            return ans

        oa, ob, oc = occurrences(a), occurrences(b), occurrences(c)
        best = n + 1
        for start in oa:
            ib = bisect_left(ob, start + len(a))
            if ib == len(ob):
                continue
            bs = ob[ib]
            ic = bisect_left(oc, bs + len(b))
            if ic == len(oc):
                continue
            end = oc[ic] + len(c)
            best = min(best, end - start)
        return -1 if best == n + 1 else best

