def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    relative = [None] * n
    answer = [0] * n
    for start in range(n):
        if relative[start] is not None:
            continue
        relative[start] = 0
        queue = [start]
        component = []
        consistent = True
        for v in queue:
            component.append(v)
            for w, z in graph[v]:
                expected = relative[v] ^ z
                if relative[w] is None:
                    relative[w] = expected
                    queue.append(w)
                elif relative[w] != expected:
                    consistent = False
        if not consistent:
            print(-1)
            return

        ones = [0] * 30
        for v in component:
            value = relative[v]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1
        offset = 0
        size = len(component)
        for bit, count in enumerate(ones):
            if count > size - count:
                offset |= 1 << bit
        for v in component:
            answer[v] = relative[v] ^ offset

    print(*answer)

if __name__ == '__main__':
    main()

