import sys

def solve_case(n, a, b):
    src = [i for i, c in enumerate(a) if c == '1']
    dst = [i for i, c in enumerate(b) if c == '1']
    if len(src) < len(dst):
        return -1

    def feasible(d):
        j = 0
        for y in dst:
            lo = y - d
            hi = y + d
            if j >= len(src) or src[j] > hi:
                return False
            if src[j] < lo:
                return False
            while j < len(src) and src[j] <= hi:
                j += 1
        return j == len(src)

    low, high = 0, n
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid
        else:
            low = mid + 1
    return low if feasible(low) else -1

def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    p = 1
    out = []
    for _ in range(t):
        n = int(data[p]); a = data[p+1].decode(); b = data[p+2].decode(); p += 3
        out.append(str(solve_case(n, a, b)))
    print('\n'.join(out))

if __name__ == '__main__':
    main()

