from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder traversal: avoids recursion-depth limits.
        order = []
        stack = [(0, False)]
        while stack:
            v, exiting = stack.pop()
            if exiting:
                order.append(v)
            else:
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))

        pos = [0] * n
        for i, v in enumerate(order):
            pos[v] = i

        # In postorder, each child's size can be added to its parent.
        subtree_size = [1] * n
        for v in order:
            if v != 0:
                subtree_size[parent[v]] += subtree_size[v]

        text = ''.join(s[v] for v in order)

        # Manacher radii for odd-length and even-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for v in range(n):
            end = pos[v]
            length = subtree_size[v]
            start = end - length + 1
            if length % 2:
                center = (start + end) // 2
                answer[v] = odd[center] >= length // 2 + 1
            else:
                center = (start + end + 1) // 2
                answer[v] = even[center] >= length // 2
        return answer

