from typing import List

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        end_a = [0] * n
        end_b = [0] * n
        end_a[0] = energyDrinkA[0]
        end_b[0] = energyDrinkB[0]

        for i in range(1, n):
            end_a[i] = energyDrinkA[i] + max(
                end_a[i - 1], end_b[i - 2] if i >= 2 else 0
            )
            end_b[i] = energyDrinkB[i] + max(
                end_b[i - 1], end_a[i - 2] if i >= 2 else 0
            )

        return max(end_a[-1], end_b[-1])

