class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - ord('a')] += 1

        for _ in range(t):
            nxt = [0] * 26
            for i in range(25):
                nxt[i + 1] = cnt[i]
            nxt[0] = cnt[25]
