import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        prime = [True] * 10000
        prime[0] = prime[1] = False
        for p in range(2, 100):
            if prime[p]:
                for x in range(p * p, 10000, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        dist = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            digits = str(value)
            for i, char in enumerate(digits):
                digit = int(char)
                for next_digit in (digit - 1, digit + 1):
                    if 0 <= next_digit <= 9:
                        neighbor = int(digits[:i] + str(next_digit) + digits[i + 1:])
                        if not prime[neighbor]:
                            next_cost = cost + neighbor
                            if next_cost < dist.get(neighbor, float('inf')):
                                dist[neighbor] = next_cost
                                heapq.heappush(heap, (next_cost, neighbor))

        return -1

