from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[k] is the LCP length of nums and nums[k:]
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            if k < right:
                z[k] = min(right - k, z[k - left])
            while k + z[k] < n and nums[z[k]] == nums[k + z[k]]:
                z[k] += 1
            if k + z[k] > right:
                left, right = k, k + z[k]

        answer = 0
        for i in range(1, n - 1):
            first_condition = z[i] >= i
            if first_condition:
                # The second part must have length at least i, and the third
                # part must remain nonempty.
                answer += max(0, n - 2 * i)

            # For each possible second-part length d, use a Z-array on nums[i:].
            suffix = nums[i:]
            m = len(suffix)
            local_z = [0] * m
            left = right = 0
            for d in range(1, m):
                if d < right:
                    local_z[d] = min(right - d, local_z[d - left])
                while d + local_z[d] < m and suffix[local_z[d]] == suffix[d + local_z[d]]:
                    local_z[d] += 1
                if d + local_z[d] > right:
                    left, right = d, d + local_z[d]

                # nums[i:i+d] is a prefix of nums[i+d:] iff local_z[d] >= d.
                # Exclude splits already counted by the first condition.
                if local_z[d] >= d and not (first_condition and d >= i):
                    answer += 1

        return answer

